{
  "claims": [
    {
      "claim": "The bill would change grade ranges relating to student discipline in Tennessee Code Annotated, Section 49-6-3402.",
      "summary_quote": "This bill would change the grade ranges for student discipline as described in Tennessee Code Annotated, Section 49-6-3402.",
      "verdict": "supported",
      "source_quote": "SECTION 1. Tennessee Code Annotated, Section 49-6-3402, is amended by deleting\n\n\"grades one through six (1-6)\" wherever it appears in the section and substituting \"grades one\n\nthrough five (1-5)\" and by deleting \"grades seven through twelve (7-12)\" wherever it appears in\n\nthe section and substituting \"grades six through twelve (6-12)\".",
      "error_type": "none",
      "rationale": "Section 1 changes the grade ranges in the named section, and the act's title identifies its subject as student discipline."
    },
    {
      "claim": "The bill would replace references to grades one through six with grades one through five.",
      "summary_quote": "It would replace references to grades one through six with grades one through five",
      "verdict": "supported",
      "source_quote": "\"grades one through six (1-6)\" wherever it appears in the section and substituting \"grades one\n\nthrough five (1-5)\"",
      "error_type": "none",
      "rationale": "The bill expressly makes this replacement wherever the original range appears in the section."
    },
    {
      "claim": "The bill would replace references to grades seven through twelve with grades six through twelve.",
      "summary_quote": "replace references to grades seven through twelve with grades six through twelve.",
      "verdict": "supported",
      "source_quote": "by deleting \"grades seven through twelve (7-12)\" wherever it appears in\n\nthe section and substituting \"grades six through twelve (6-12)\".",
      "error_type": "none",
      "rationale": "The bill expressly makes this replacement wherever the original range appears in the section."
    },
    {
      "claim": "The bill would take effect upon becoming law.",
      "summary_quote": "The bill would take effect as soon as it becomes law.",
      "verdict": "supported",
      "source_quote": "SECTION 2. This act takes effect upon becoming a law, the public welfare requiring it.",
      "error_type": "none",
      "rationale": "The summary accurately states the effective-date provision."
    }
  ]
}
